/* Suite run, family stub2 (plan 07-05, D-09, D-10, A-09, A-17): the project boot stub contract 2, the listing
 * fixtures/FX-boot-stub-2/boot-stub-2.listing.txt generated by ivs_asm from boot-stub-2.asm and packed by
 * tools/pack into the build-tree EXEC image whose bytes ivs_images.inc carries, loaded with a 2048-byte zero GROM (a
 * project stand-in, not a GROM) and driven from a power-on reset through the public API. Every expected value is a
 * literal from that listing or from the probe source tests/run/stub2-probe.asm, never read back from the code under
 * test. No image byte is committed (D-30).
 *   run.stub2.path       one run call per unit (target now + 1): R7 at the start of each unit after the reset entry
 *                        unit is 1000, 1010, 1011, 1013, 5000, the reset path of contract 1 word for word (B $1010,
 *                        DIS, MVII #$0340,R6, J $5000); the image words of that path equal those of contract 1 and
 *                        the interrupt entry words 1004..1006 are 0004, 0352, 0004 (JD $5004).
 *   run.stub2.handoff    with the probe cartridge (EIS and a wait at 5000; at 5004 the marker word, the entry counter
 *                        word, then a wait without EIS) one frame is run unit by unit: the interrupt request of the
 *                        frame enters 1004 once, the next unit is at 5004 with interrupts off and R6 = 0341, and at
 *                        the end of the frame (59,736 ticks) the marker word is 03C5, the counter word is 0001, R6 is
 *                        still 0341 and the CPU waits at 500D with interrupts off.
 *   run.stub2.jd-as-j    the control STUB2_JD_AS_J (A-17), without a core fault: a heap copy of the stub 2 image with
 *                        the second decle of the vector (word 1005, 0352 for JD) changed to the J form (0350) shows
 *                        more than one interrupt entry in the frame, interrupts still on after the vector, and R6
 *                        above 0341 at the end of the frame: a plain J is a trap (D-10). */
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "ivs/ivs.h"
#include "ivs_test.h"
#include "machine/machine.h"
#include "run_cases.h"

#include "ivs_images.inc"

#define IVS_CHECK(cond)                                                                                \
  do {                                                                                                 \
    if (!(cond)) {                                                                                     \
      ivs_test_diag("check failed at line %d: %s", __LINE__, #cond);                                   \
      return IVS_TEST_FAIL;                                                                            \
    }                                                                                                  \
  } while (0)

/* Like IVS_CHECK, inside a case that must release its instance (label done). */
#define RS2_CHECK(cond)                                                                                \
  do {                                                                                                 \
    if (!(cond)) {                                                                                     \
      ivs_test_diag("check failed at line %d: %s", __LINE__, #cond);                                   \
      goto done;                                                                                       \
    }                                                                                                  \
  } while (0)

#define RS2_POISON 0x5Au
#define RS2_ZERO_GROM_BYTES 2048u
#define RS2_FRAME_TICKS 59736u /* one nominal frame: 262 lines x 57 cycles x 4 ticks */
#define RS2_MAX_UNITS 20000u   /* a bound on one frame of single units (about 2,500 are run) */

/* R7 at the start of the units after the reset entry (listing lines 1000, 1010, 1011, 1013, then the cartridge entry
 * 5000): the same path as contract 1. */
static const uint16_t rs2_path_r7[] = {0x1000u, 0x1010u, 0x1011u, 0x1013u, 0x5000u};

/* ---- helpers ---- */

/* A heap copy of n bytes at src (ivs_ms_load frees it), or NULL. */
static uint8_t *rs2_copy(const uint8_t *src, size_t n)
{
  uint8_t *b = malloc(n);
  if (b != NULL) {
    memcpy(b, src, n);
  }
  return b;
}

/* A powered instance: stub contract 2 EXEC from bytes (consumed), 2048 zero bytes as GROM, the probe cartridge when
 * with_probe is set, a power-on reset. 1 on success. */
static int rs2_powered(ivs_ms_inst *x, uint8_t *exec, int with_probe)
{
  ivs_status st;
  if (!ivs_ms_new(x, RS2_POISON)) {
    free(exec);
    return 0;
  }
  if (!ivs_ms_load(x->m, IVS_KIND_EXEC, exec, IVS_IMG_BOOT_STUB_2_BYTES) ||
      !ivs_ms_load(x->m, IVS_KIND_GROM, calloc(RS2_ZERO_GROM_BYTES, 1u), RS2_ZERO_GROM_BYTES) ||
      (with_probe && !ivs_ms_load(x->m, IVS_KIND_CARTRIDGE, rs2_copy(ivs_img_stub2_probe, IVS_IMG_STUB2_PROBE_BYTES),
                                  IVS_IMG_STUB2_PROBE_BYTES))) {
    ivs_ms_free(x);
    return 0;
  }
  st = ivs_machine_reset(x->m, IVS_RESET_POWER_ON);
  if (st != IVS_OK) {
    ivs_test_diag("reset refused (%s)", ivs_status_name(st));
    ivs_ms_free(x);
    return 0;
  }
  return 1;
}

static int rs2_cpu(const ivs_machine *m, ivs_cpu_state_report *r)
{
  memset(r, 0, sizeof *r);
  r->struct_size = (uint32_t)sizeof *r;
  if (ivs_machine_cpu_state(m, r) != IVS_OK) {
    ivs_test_diag("cpu_state refused");
    return 0;
  }
  return 1;
}

/* One run call to now + 1 (exactly one unit); 1 when it ran one unit and stopped at the target. The machine time at
 * the end of the unit goes to *now_after when that is not NULL. */
static int rs2_one_unit(ivs_machine *m, uint64_t *now_after)
{
  ivs_info info;
  ivs_run_request q;
  ivs_run_report rep;
  ivs_status st;
  memset(&info, 0, sizeof info);
  info.struct_size = (uint32_t)sizeof info;
  if (ivs_machine_info(m, &info) != IVS_OK) {
    ivs_test_diag("info refused");
    return 0;
  }
  memset(&q, 0, sizeof q);
  q.struct_size = (uint32_t)sizeof q;
  q.target_ticks = info.time_ticks + 1u;
  memset(&rep, 0, sizeof rep);
  rep.struct_size = (uint32_t)sizeof rep;
  st = ivs_machine_run(m, &q, &rep);
  if (st != IVS_OK || rep.stop_reason != IVS_STOP_TARGET || rep.units_executed != 1u) {
    ivs_test_diag("run to now + 1: status %s stop %u units %llu", ivs_status_name(st), (unsigned)rep.stop_reason,
                  (unsigned long long)rep.units_executed);
    return 0;
  }
  if (now_after != NULL) {
    *now_after = rep.now_ticks;
  }
  return 1;
}

/* The word at addr through the public read view (0xFFFF when peek refuses). */
static uint16_t rs2_peek(const ivs_machine *m, uint16_t addr)
{
  uint16_t w = 0xFFFFu;
  if (ivs_machine_peek(m, addr, 1u, &w) != IVS_OK) {
    ivs_test_diag("peek %04X refused", (unsigned)addr);
    return 0xFFFFu;
  }
  return w;
}

/* Drives a powered contract 2 instance from reset to the first unit at the cartridge entry 5000, checking the path;
 * 1 when every check holds. */
static int rs2_to_entry(ivs_ms_inst *x, uint64_t *now_after)
{
  ivs_cpu_state_report r;
  size_t k;
  if (!rs2_cpu(x->m, &r)) {
    return 0;
  }
  if (r.run_state != IVS_CPU_STATE_RESET_PENDING) {
    ivs_test_diag("after reset: run_state %u, want RESET_PENDING", (unsigned)r.run_state);
    return 0;
  }
  for (k = 0u; k < sizeof rs2_path_r7 / sizeof rs2_path_r7[0]; k++) {
    if (!rs2_one_unit(x->m, now_after) || !rs2_cpu(x->m, &r)) {
      return 0;
    }
    if (r.run_state != IVS_CPU_STATE_RUNNING || r.r[7] != rs2_path_r7[k]) {
      ivs_test_diag("unit %u: run_state %u R7 %04X, want RUNNING and R7 %04X", (unsigned)(k + 1u),
                    (unsigned)r.run_state, (unsigned)r.r[7], (unsigned)rs2_path_r7[k]);
      return 0;
    }
    /* After DIS (R7 = 1011) the interrupt system is off; after MVII #$0340,R6 (R7 = 1013) R6 is the project stack
     * start. */
    if ((rs2_path_r7[k] == 0x1011u && r.intr_enabled != 0u) || (rs2_path_r7[k] == 0x1013u && r.r[6] != 0x0340u)) {
      ivs_test_diag("unit %u: intr_enabled %u R6 %04X", (unsigned)(k + 1u), (unsigned)r.intr_enabled,
                    (unsigned)r.r[6]);
      return 0;
    }
  }
  return 1;
}

/* What one frame of single units showed: the number of units that ended at the interrupt entry 1004, and the state
 * of the first unit after the first of them (the vector). */
typedef struct rs2_frame {
  uint32_t entries;
  uint16_t vec_r7;
  uint16_t vec_r6;
  uint8_t vec_intr;
  uint8_t vec_seen;
} rs2_frame;

/* From the first unit at 5000, runs units one by one until machine time reaches the end of frame 0 (RS2_FRAME_TICKS),
 * counting the units that end at the interrupt entry 1004. 1 on success. */
static int rs2_run_frame(ivs_machine *m, uint64_t now, rs2_frame *f)
{
  ivs_cpu_state_report r;
  uint32_t guard;
  int after_first = 0;
  memset(f, 0, sizeof *f);
  for (guard = 0u; now < RS2_FRAME_TICKS; guard++) {
    if (guard >= RS2_MAX_UNITS) {
      ivs_test_diag("no end of frame after %u units (now %llu)", (unsigned)guard, (unsigned long long)now);
      return 0;
    }
    if (!rs2_one_unit(m, &now) || !rs2_cpu(m, &r)) {
      return 0;
    }
    if (after_first) {
      f->vec_r7 = r.r[7];
      f->vec_r6 = r.r[6];
      f->vec_intr = r.intr_enabled;
      f->vec_seen = 1u;
      after_first = 0;
    }
    if (r.r[7] == 0x1004u) {
      f->entries++;
      after_first = f->entries == 1u;
    }
  }
  return 1;
}

/* ---- cases ---- */

static int rs2_path(void)
{
  ivs_ms_inst x;
  uint8_t *img;
  size_t k;
  int rc = IVS_TEST_FAIL;
  /* The words of the listing (big-endian pairs, word 1000 first): the reset path of contract 1 and the vector. */
  static const uint8_t reset_words[][2] = {{0x02u, 0x00u}, {0x00u, 0x0Eu}}; /* 1000 B, 1001 displacement 000E */
  static const uint8_t reset_tail[][2] = {{0x00u, 0x03u}, {0x02u, 0xBEu}, {0x03u, 0x40u},
                                          {0x00u, 0x04u}, {0x03u, 0x50u}, {0x00u, 0x00u}}; /* 1010..1015 */
  static const uint8_t vector_words[][2] = {{0x00u, 0x04u}, {0x03u, 0x52u}, {0x00u, 0x04u}}; /* 1004..1006 JD $5004 */
  IVS_CHECK(IVS_IMG_BOOT_STUB_2_BYTES == 8192u);
  img = rs2_copy(ivs_img_boot_stub_2, IVS_IMG_BOOT_STUB_2_BYTES);
  IVS_CHECK(img != NULL);
  for (k = 0u; k < 2u; k++) {
    if (memcmp(img + 2u * k, reset_words[k], 2u) != 0) {
      ivs_test_diag("image word %04X is not the listing word", (unsigned)(0x1000u + k));
      free(img);
      return IVS_TEST_FAIL;
    }
  }
  for (k = 0u; k < 6u; k++) {
    if (memcmp(img + 2u * (0x10u + k), reset_tail[k], 2u) != 0) {
      ivs_test_diag("image word %04X is not the listing word", (unsigned)(0x1010u + k));
      free(img);
      return IVS_TEST_FAIL;
    }
  }
  for (k = 0u; k < 3u; k++) {
    if (memcmp(img + 2u * (4u + k), vector_words[k], 2u) != 0) {
      ivs_test_diag("image word %04X is not the listing word", (unsigned)(0x1004u + k));
      free(img);
      return IVS_TEST_FAIL;
    }
  }
  IVS_CHECK(rs2_powered(&x, img, 0));
  RS2_CHECK(rs2_to_entry(&x, NULL));
  rc = IVS_TEST_PASS;
done:
  ivs_ms_free(&x);
  return rc;
}

static int rs2_handoff(void)
{
  ivs_ms_inst x;
  ivs_cpu_state_report r;
  rs2_frame f;
  uint64_t now = 0u;
  int rc = IVS_TEST_FAIL;
  IVS_CHECK(IVS_IMG_STUB2_PROBE_BYTES > 0u);
  IVS_CHECK(rs2_powered(&x, rs2_copy(ivs_img_boot_stub_2, IVS_IMG_BOOT_STUB_2_BYTES), 1));
  RS2_CHECK(rs2_to_entry(&x, &now));
  RS2_CHECK(rs2_peek(x.m, 0x02F0u) == 0x0000u && rs2_peek(x.m, 0x02F1u) == 0x0000u);
  RS2_CHECK(rs2_run_frame(x.m, now, &f));
  /* One entry at 1004, then the vector JD: at 5004 with interrupts off and the return address pushed. */
  RS2_CHECK(f.entries == 1u);
  RS2_CHECK(f.vec_seen == 1u && f.vec_r7 == 0x5004u && f.vec_intr == 0u && f.vec_r6 == 0x0341u);
  /* The routine ran once, to its wait at 500D, without turning interrupts on again. */
  RS2_CHECK(rs2_peek(x.m, 0x02F0u) == 0x03C5u);
  RS2_CHECK(rs2_peek(x.m, 0x02F1u) == 0x0001u);
  RS2_CHECK(rs2_cpu(x.m, &r));
  RS2_CHECK(r.run_state == IVS_CPU_STATE_RUNNING && r.r[7] == 0x500Du && r.r[6] == 0x0341u && r.intr_enabled == 0u);
  rc = IVS_TEST_PASS;
done:
  ivs_ms_free(&x);
  return rc;
}

static int rs2_jd_as_j(void)
{
  ivs_ms_inst x;
  ivs_cpu_state_report r;
  rs2_frame f;
  uint8_t *patched;
  uint64_t now = 0u;
  int rc = IVS_TEST_FAIL;
  /* The second decle of the vector, image offset 2 * (1005 - 1000): 0352 is the JD form (BB = 11, target bits 15..10
   * = 010100, EE = 10); 0350 is the J form (EE = 00). */
  patched = rs2_copy(ivs_img_boot_stub_2, IVS_IMG_BOOT_STUB_2_BYTES);
  IVS_CHECK(patched != NULL);
  if (patched[2u * 5u] != 0x03u || patched[2u * 5u + 1u] != 0x52u) {
    ivs_test_diag("image word 1005 is not the JD decle 0352");
    free(patched);
    return IVS_TEST_FAIL;
  }
  patched[2u * 5u + 1u] = 0x50u;
  IVS_CHECK(rs2_powered(&x, patched, 1));
  RS2_CHECK(rs2_to_entry(&x, &now));
  RS2_CHECK(rs2_run_frame(x.m, now, &f));
  RS2_CHECK(f.entries > 1u);
  RS2_CHECK(f.vec_seen == 1u && f.vec_r7 == 0x5004u && f.vec_intr == 1u);
  RS2_CHECK(rs2_cpu(x.m, &r));
  RS2_CHECK(r.r[6] > 0x0341u);
  rc = IVS_TEST_PASS;
done:
  ivs_ms_free(&x);
  return rc;
}

const ivs_test_case ivs_run_stub2_cases[] = {
    {"run.stub2.path", rs2_path, NULL},
    {"run.stub2.handoff", rs2_handoff, NULL},
    {"run.stub2.jd-as-j", rs2_jd_as_j, NULL},
};

const size_t ivs_run_stub2_count = sizeof ivs_run_stub2_cases / sizeof ivs_run_stub2_cases[0];
